// ***************
// Filename: axis_dma_regs.sv
// Author: FPGA Cores 4 U
// Description: Register map of axis_dma: its AXI4-Lite register slave
//   (axi4_lite_slave front end) with every register of the block, the ID
//   block first; the registers go to axis_dma's logic on named ports, its
//   status comes back on input ports. AXI-Stream DMA: start control, MM2S /
//   S2MM address and length, status. Generated by ip/scripts/regmap_gen.py
//   from axis_dma_regs.json: edit the JSON and regenerate (the IP_VERSION /
//   IP_DATE stamps are kept).
//   Register map (ADDR_W = 8, byte offsets):
//     0x00 ID          RO   "ADMA" IP identifier, 4 ASCII characters (first
//                       in [31:24])
//     0x04 VERSION     RO   version, ASCII "d.dd" (+0.01 at every source
//                       update)
//     0x08 DATE        RO   date of the last source update, BCD mm/dd/yyyy
//                       (0xMMDDYYYY)
//     0x0C reserved    RO   0
//     0x10 CTRL        RW   control, reset 0x0
//                       [0] MM2S_START: write 1: start a memory to stream
//                         transfer
//                       [1] S2MM_START: write 1: start a stream to memory
//                         transfer
//                       [2] IRQ_EN: irq_o on a done flag
//     0x14 MM2S_ADDR   RW   MM2S source address (bytes), reset 0x0
//     0x18 MM2S_LEN    RW   MM2S length in bytes (multiple of 4, not 0),
//                       reset 0x0
//     0x1C S2MM_ADDR   RW   S2MM destination address (bytes), reset 0x0
//     0x20 S2MM_LEN    RW   S2MM length in bytes (multiple of 4, not 0),
//                       reset 0x0
//     0x24 STATUS      CMD  status; done and error bits write 1 to clear
//                       [0] MM2S_BUSY: MM2S running
//                       [1] S2MM_BUSY: S2MM running
//                       [8] MM2S_DONE: MM2S finished (W1C)
//                       [9] S2MM_DONE: S2MM finished (W1C)
//                       [10] MM2S_ERR: MM2S bad length or bus error (W1C)
//                       [11] S2MM_ERR: S2MM bad length or bus error (W1C)
//   Access: RW read / write (byte strobes), RO read only (writes answer
//   SLVERR), W1C hardware sets / software writes 1 to clear (a set wins), W1S
//   software writes 1 to set / hardware clears, WO write only (reads 0), CMD
//   reads the hardware value, a write gives a pulse with its data. Unmapped
//   words read 0 and ignore writes; above the map: DECERR. Clock - aclk.
//   Reset - synchronous active low aresetn. Latency - 2 clocks per write and
//   read.
// Date: 2026-10-12
module axis_dma_regs (
  input  logic          aclk,           // clock
  input  logic          aresetn,        // synchronous reset, active low
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 8
  input  logic [7:0]    s_axil_awaddr,  // AXI4-Lite
  input  logic          s_axil_awvalid,
  output logic          s_axil_awready,
  input  logic [31:0]   s_axil_wdata,
  input  logic [3:0]    s_axil_wstrb,
  input  logic          s_axil_wvalid,
  output logic          s_axil_wready,
  output logic [1:0]    s_axil_bresp,
  output logic          s_axil_bvalid,
  input  logic          s_axil_bready,
  input  logic [7:0]    s_axil_araddr,
  input  logic          s_axil_arvalid,
  output logic          s_axil_arready,
  output logic [31:0]   s_axil_rdata,
  output logic [1:0]    s_axil_rresp,
  output logic          s_axil_rvalid,
  input  logic          s_axil_rready,
  output logic [3-1:0]  ctrl_o,         // CTRL (RW): register value
  output logic          ctrl_wr_o,      // CTRL: one-clock pulse at every software write
  output logic [32-1:0] mm2s_addr_o,    // MM2S_ADDR (RW): register value
  output logic          mm2s_addr_wr_o, // MM2S_ADDR: one-clock pulse at every software write
  output logic [32-1:0] mm2s_len_o,     // MM2S_LEN (RW): register value
  output logic          mm2s_len_wr_o,  // MM2S_LEN: one-clock pulse at every software write
  output logic [32-1:0] s2mm_addr_o,    // S2MM_ADDR (RW): register value
  output logic          s2mm_addr_wr_o, // S2MM_ADDR: one-clock pulse at every software write
  output logic [32-1:0] s2mm_len_o,     // S2MM_LEN (RW): register value
  output logic          s2mm_len_wr_o,  // S2MM_LEN: one-clock pulse at every software write
  input  logic [12-1:0] status_i,       // STATUS (CMD): value read
  output logic [12-1:0] status_o,       // STATUS (CMD): data written
  output logic          status_wr_o     // STATUS: one-clock pulse at every software write
);
  // ---------------- register map
  localparam logic [31:0] IP_ID      = "ADMA";
  localparam logic [31:0] IP_VERSION = "1.10";
  localparam logic [31:0] IP_DATE    = 32'h10122026;   // mm/dd/yyyy, BCD
  localparam logic [7:0] A_ID = 8'h0, A_VERSION = 8'h4, A_DATE = 8'h8;
  localparam logic [7:0] A_CTRL = 8'h10;
  localparam logic [7:0] A_MM2S_ADDR = 8'h14;
  localparam logic [7:0] A_MM2S_LEN = 8'h18;
  localparam logic [7:0] A_S2MM_ADDR = 8'h1C;
  localparam logic [7:0] A_S2MM_LEN = 8'h20;
  localparam logic [7:0] A_STATUS = 8'h24;
  localparam int MAP_WORDS = 10;

  logic             wr_en, rd_en, wr_err_q;
  logic [7:0]       wr_addr, rd_addr, rd_addr_q;
  logic [31:0]      wr_data, rd_data;
  logic [3:0]       wr_strb;
  axi4_lite_slave #(
    .ADDR_W(8),
    .READ_WAIT(0),
    .MAP_WORDS(MAP_WORDS)
  ) u_axil (
    .aclk(aclk),
    .aresetn(aresetn),
    .s_axil_awaddr,
    .s_axil_awvalid,
    .s_axil_awready,
    .s_axil_wdata,
    .s_axil_wstrb,
    .s_axil_wvalid,
    .s_axil_wready,
    .s_axil_bresp,
    .s_axil_bvalid,
    .s_axil_bready,
    .s_axil_araddr,
    .s_axil_arvalid,
    .s_axil_arready,
    .s_axil_rdata,
    .s_axil_rresp,
    .s_axil_rvalid,
    .s_axil_rready,
    .wr_en_o(wr_en),
    .wr_addr_o(wr_addr),
    .wr_data_o(wr_data),
    .wr_strb_o(wr_strb),
    .wr_err_i(wr_err_q),
    .rd_en_o(rd_en),
    .rd_addr_o(rd_addr),
    .rd_data_i(rd_data),
    .rd_valid_i(1'b1),
    .rd_err_i(1'b0)
  );
  wire [7:0] wa = {wr_addr[7:2], 2'b00};
  // byte strobes applied to the written word
  logic [31:0] wmask;
  always_comb for (int b = 0; b < 4; b++) wmask[b*8 +: 8] = {8{wr_strb[b]}};

  // ---------------- writes
  logic [31:0] ctrl_q;
  logic [31:0] mm2s_addr_q;
  logic [31:0] mm2s_len_q;
  logic [31:0] s2mm_addr_q;
  logic [31:0] s2mm_len_q;
  logic [31:0] status_q;
  always_ff @(posedge aclk) begin
    if (!aresetn) begin
      ctrl_q <= 32'h0;
      ctrl_wr_o <= 1'b0;
      mm2s_addr_q <= 32'h0;
      mm2s_addr_wr_o <= 1'b0;
      mm2s_len_q <= 32'h0;
      mm2s_len_wr_o <= 1'b0;
      s2mm_addr_q <= 32'h0;
      s2mm_addr_wr_o <= 1'b0;
      s2mm_len_q <= 32'h0;
      s2mm_len_wr_o <= 1'b0;
      status_q <= '0;
      status_wr_o <= 1'b0;
      wr_err_q <= 1'b0;
    end else begin
      wr_err_q <= wr_en && (wa == A_ID || wa == A_VERSION || wa == A_DATE);   // writes to read-only words: SLVERR
      begin
        ctrl_wr_o <= wr_en && wa == A_CTRL;
        if (wr_en && wa == A_CTRL) ctrl_q <= (ctrl_q & ~wmask) | (wr_data & wmask);
      end
      begin
        mm2s_addr_wr_o <= wr_en && wa == A_MM2S_ADDR;
        if (wr_en && wa == A_MM2S_ADDR) mm2s_addr_q <= (mm2s_addr_q & ~wmask) | (wr_data & wmask);
      end
      begin
        mm2s_len_wr_o <= wr_en && wa == A_MM2S_LEN;
        if (wr_en && wa == A_MM2S_LEN) mm2s_len_q <= (mm2s_len_q & ~wmask) | (wr_data & wmask);
      end
      begin
        s2mm_addr_wr_o <= wr_en && wa == A_S2MM_ADDR;
        if (wr_en && wa == A_S2MM_ADDR) s2mm_addr_q <= (s2mm_addr_q & ~wmask) | (wr_data & wmask);
      end
      begin
        s2mm_len_wr_o <= wr_en && wa == A_S2MM_LEN;
        if (wr_en && wa == A_S2MM_LEN) s2mm_len_q <= (s2mm_len_q & ~wmask) | (wr_data & wmask);
      end
      begin
        status_wr_o <= wr_en && wa == A_STATUS;
        if (wr_en && wa == A_STATUS) status_q <= (status_q & ~wmask) | (wr_data & wmask);
      end
    end
  end
  assign ctrl_o = ctrl_q[3-1:0];
  assign mm2s_addr_o = mm2s_addr_q[32-1:0];
  assign mm2s_len_o = mm2s_len_q[32-1:0];
  assign s2mm_addr_o = s2mm_addr_q[32-1:0];
  assign s2mm_len_o = s2mm_len_q[32-1:0];
  assign status_o = status_q[12-1:0];

  // ---------------- reads: the word addressed in the clock before
  always_ff @(posedge aclk) if (rd_en) rd_addr_q <= {rd_addr[7:2], 2'b00};
  always_comb begin
    rd_data = '0;
    case (rd_addr_q)
      A_ID:      rd_data = IP_ID;
      A_VERSION: rd_data = IP_VERSION;
      A_DATE:    rd_data = IP_DATE;
      A_CTRL: rd_data = ctrl_q;
      A_MM2S_ADDR: rd_data = mm2s_addr_q;
      A_MM2S_LEN: rd_data = mm2s_len_q;
      A_S2MM_ADDR: rd_data = s2mm_addr_q;
      A_S2MM_LEN: rd_data = s2mm_len_q;
      A_STATUS: rd_data = 32'(status_i);
      default: begin
      end
    endcase
  end
endmodule
